export default function config({ owner, project, path, tag }) {
  for (const [k, v] of Object.entries({ owner, project, path, tag }))
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_")) throw Error("Configure " + k);
  if (
    owner.split("/").some((x) => !x || x === "." || x === ".." || !/^[A-Za-z0-9_.-]+$/.test(x)) ||
    project === "." ||
    project === ".." ||
    !/^[A-Za-z0-9_.-]+$/.test(project) ||
    path.startsWith("/") ||
    path.endsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..") ||
    tag.split(",").some((x) => !x.trim())
  )
    throw Error("Invalid repository configuration");
  const p = "/projects/" + encodeURIComponent(owner + "/" + project);
  return {
    owner,
    project,
    path,
    tag: tag
      .split(",")
      .map((x) => x.trim())
      .join(","),
    projectEndpoint: p,
    branchEndpoint: p + "/repository/branches/main",
  };
}

