export default function validate({ body, statusCode, bodyEncoding, expected, kind }) {
  if (statusCode !== 200 || bodyEncoding || !body || typeof body !== "object")
    throw Error("GitLab " + kind + " is unavailable");
  if (kind === "branch" && body.name !== expected) throw Error("GitLab branch mismatch");
  if (kind === "project" && !(typeof body.id === "number" || typeof body.id === "string"))
    throw Error("Invalid GitLab project");
  return { ok: true };
}

