export default async function pages({ tag, previous }, context) {
  const s = previous ?? { items: [], cursor: null, seen: [] };
  const r = await context.actions.call("n8n.list_workflows", {
    tags: tag.split(",").map((x) => x.trim()),
    limit: 100,
    ...(s.cursor ? { cursor: s.cursor } : {}),
  });
  if (!Array.isArray(r?.data)) throw Error("Invalid workflow page");
  const c = r.nextCursor;
  if (c !== null && (typeof c !== "string" || !c || s.seen.includes(c)))
    throw Error("Invalid or repeated cursor");
  return {
    state: { items: s.items.concat(r.data), cursor: c, seen: c ? [...s.seen, c] : s.seen },
    more: c !== null,
  };
}

