export default function plan({ state, path, projectEndpoint }) {
  if (!Array.isArray(state.items)) throw Error("Invalid workflows");
  const seen = new Set(),
    items = [];
  for (const w of state.items) {
    if (!w || typeof w.name !== "string" || !w.name.trim() || typeof w.id !== "string" || !w.id)
      throw Error("Invalid workflow");
    const n = w.name.replace(/[^a-zA-Z0-9]/g, "") + ".json";
    if (n === ".json" || seen.has(n)) throw Error("Workflow filenames collide or are empty");
    seen.add(n);
    const filePath = path + "/" + n;
    items.push({
      workflow: w,
      filePath,
      endpoint: projectEndpoint + "/repository/files/" + encodeURIComponent(filePath),
      content: JSON.stringify(w, null, 4),
    });
  }
  return { items };
}

