export default function next({ items, previous }) {
  const i = previous?.index ?? 0;
  if (!Array.isArray(items)) throw Error("Invalid backup plan");
  return i < items.length
    ? {
        state: { index: i + 1 },
        more: true,
        item: items[i],
        endpoint: items[i].endpoint + "?ref=main",
      }
    : { state: { index: i }, more: false, item: {}, endpoint: "/unused" };
}

