import { Buffer } from "node:buffer";
export default function compare({ body, statusCode, bodyEncoding, item }) {
  if (bodyEncoding || !item || typeof item.content !== "string")
    throw Error("Invalid GitLab response");
  let exists = false,
    changed = true,
    lastCommit = null;
  if (statusCode === 200) {
    if (
      !body ||
      body.file_path !== item.filePath ||
      body.encoding !== "base64" ||
      typeof body.content !== "string" ||
      typeof body.last_commit_id !== "string" ||
      !body.last_commit_id
    )
      throw Error("Invalid GitLab file");
    const b = Buffer.from(body.content.replace(/\s/g, ""), "base64");
    if (
      !b.length ||
      b.toString("base64").replace(/=+$/, "") !== body.content.replace(/\s|=+$/g, "")
    )
      throw Error("Invalid GitLab file content");
    exists = true;
    changed = b.toString("utf8") !== item.content;
    lastCommit = body.last_commit_id;
  } else if (statusCode !== 404) throw Error("GitLab file lookup failed");
  const common = { branch: "main", content: item.content, commit_message: "Back up n8n workflow" };
  return {
    exists,
    changed,
    endpoint: item.endpoint,
    createBody: common,
    updateBody: { ...common, last_commit_id: lastCommit ?? "" },
  };
}

