export default function confirm({ body, statusCode, bodyEncoding, item }) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    bodyEncoding ||
    body?.file_path !== item.filePath ||
    body?.branch !== "main"
  )
    throw Error("GitLab write not confirmed");
  return { ok: true };
}

